import{_ as s,C as i,c as t,o as d,a6 as u,G as o,j as e,a as n}from"./chunks/framework.BY05barL.js";const c="/ucasal-ssoo-estudio/assets/4-fallos-pagina.pMfs4vcK.png",q=JSON.parse('{"title":"Fallos de Página","description":"","frontmatter":{},"headers":[],"relativePath":"unidad3/fallos-pagina.md","filePath":"unidad3/fallos-pagina.md"}'),p={name:"unidad3/fallos-pagina.md"};function g(m,a,f,P,v,b){const l=i("PageFaultDiagram"),r=i("PageFaultSteps");return d(),t("div",null,[a[0]||(a[0]=u('<h1 id="fallos-de-pagina" tabindex="-1">Fallos de Página <a class="header-anchor" href="#fallos-de-pagina" aria-label="Permalink to &quot;Fallos de Página&quot;">​</a></h1><p>Un <strong>fallo de página</strong> (page fault) ocurre cuando un proceso intenta acceder a una página que no está actualmente cargada en la memoria principal (RAM), sino que se encuentra en el disco.</p><h2 id="¿cuando-ocurre-un-fallo-de-pagina" tabindex="-1">¿Cuándo Ocurre un Fallo de Página? <a class="header-anchor" href="#¿cuando-ocurre-un-fallo-de-pagina" aria-label="Permalink to &quot;¿Cuándo Ocurre un Fallo de Página?&quot;">​</a></h2><p>Un fallo de página se produce cuando:</p><ul><li>El bit de validez (V) de la entrada en la tabla de páginas es 0</li><li>La MMU no puede traducir la dirección y genera un <strong>trap</strong> al sistema operativo</li></ul><p>V=0 puede significar dos cosas, y el SO es quien las distingue:</p><ul><li>La página es del proceso pero está en disco → se carga y el proceso sigue</li><li>La página no está asociada a nada (dirección inválida) → el proceso recibe una señal o se termina (<em>segmentation fault</em>)</li></ul><h2 id="pasos-en-un-fallo-de-pagina" tabindex="-1">Pasos en un Fallo de Página <a class="header-anchor" href="#pasos-en-un-fallo-de-pagina" aria-label="Permalink to &quot;Pasos en un Fallo de Página&quot;">​</a></h2><p>Según Tanenbaum (§3.6.2), cuando ocurre un fallo de página:</p><ol><li><strong>Trap al kernel.</strong> El hardware guarda el contador de programa (PC) y una rutina guarda los registros de la CPU.</li><li><strong>¿Qué página?</strong> El SO determina qué página virtual se necesita (un registro del hardware lo indica, o analiza la instrucción que falló).</li><li><strong>¿Es válida?</strong> El SO verifica que la dirección sea válida y que el acceso esté permitido. Si no, envía una señal o termina el proceso (p. ej., <em>segmentation fault</em>).</li><li><strong>Marco.</strong> Busca un marco libre. Si no hay, ejecuta el <strong>algoritmo de reemplazo de páginas</strong> para elegir una víctima.</li><li><strong>Víctima sucia.</strong> Si la víctima fue modificada (M=1), planifica su escritura a disco. El marco se marca como ocupado, el proceso se suspende y se ejecuta otro.</li><li><strong>Leer la página.</strong> Con el marco limpio, el SO busca la página en el disco y planifica su lectura. El proceso sigue <strong>bloqueado</strong>; mientras, se ejecuta otro.</li><li><strong>Llega la página.</strong> Con la interrupción del disco, se actualiza la tabla de páginas (marco y V=1).</li><li><strong>Retroceder la instrucción.</strong> La instrucción que falló vuelve a su estado inicial y el PC apunta otra vez a ella.</li><li><strong>Planificar.</strong> El proceso que falló vuelve a estar listo y el planificador lo elige.</li><li><strong>Volver.</strong> Se restauran los registros y se vuelve a modo usuario: la instrucción se ejecuta de nuevo, ahora sin fallo.</li></ol>',10)),o(l),a[1]||(a[1]=e("h3",{id:"ejemplo-paso-a-paso",tabindex:"-1"},[n("Ejemplo paso a paso "),e("a",{class:"header-anchor",href:"#ejemplo-paso-a-paso","aria-label":'Permalink to "Ejemplo paso a paso"'},"​")],-1)),a[2]||(a[2]=e("p",null,[n("Es el caso "),e("strong",null,"b) (5, 122)"),n(" del "),e("a",{href:"./paginacion.html#ejercicio-3-traduccion-de-direcciones-virtuales"},"Ejercicio 3 de Paginación"),n(": la página 5 tiene V=0. Probá con y sin marcos libres.")],-1)),o(r),a[3]||(a[3]=e("h2",{id:"variante-paginador-externo",tabindex:"-1"},[n("Variante: paginador externo "),e("a",{class:"header-anchor",href:"#variante-paginador-externo","aria-label":'Permalink to "Variante: paginador externo"'},"​")],-1)),a[4]||(a[4]=e("p",null,[e("img",{src:c,alt:"Proceso de Fallo de Página"})],-1)),a[5]||(a[5]=e("p",null,[e("em",null,[n("La figura muestra la variante con "),e("strong",null,"paginador externo"),n(" (Tanenbaum, Fig. 3-29): un proceso en espacio de usuario se encarga de leer la página del disco, y el kernel solo maneja el fallo y la MMU.")])],-1)),a[6]||(a[6]=e("p",null,"La misma figura, paso a paso:",-1)),o(l,{variant:"external"})])}const S=s(p,[["render",g]]);export{q as __pageData,S as default};
